/*******************************************************************************
 * Size: 24 px
 * Bpp: 4
 * Opts: --bpp 4 --size 24 --no-compress --stride 1 --align 1 --font msyh.ttf --symbols 年月日星期一二三四五六七八九十
0123456789:
今天是我们结婚的第天

今天的阳光很好，你也是。
晚饭想吃什么？我请客。
风很轻，适合和你散散步。
下班路上，给你带了杯奶茶。
今天心情不错，因为你笑了。
天气正好，出去走走吧。
雨天听雷，晴天看云，身边是你。
冰箱里有你爱吃的水果。
今天换我洗碗，你歇着。
路边的花开了，想起你了。
别忙太晚，早点睡。
今天天气刚好，适合约会。
你穿那件外套特别好看。
菜买好了，回来吃饭吧。
今天有点想你，就一点点。
电影票订好了，走。
今天的云像一只猫，你看。
别皱眉了，走，吃顿好的。
你早上迷迷糊糊的样子有点可爱。
家里WiFi密码是你生日。
今天无大事，就是想和你待着。
这杯咖啡给你，少糖多奶。
别看了，手机没我好看。
今天穿暖点，风大。
超市逛一圈，给你买点零食。
今晚星星很多，出去看看？
你做饭，我洗碗，公平吧？
路上注意安全，到了说一声。
你笑起来，比今天天气还好。
别太累了，我在家等你。
今天也很好，明天也是。

新年第一天，我们的脚步也要同步。
今天哪里都不去，只想和你在一起。
我知道，这是你对我的无声告白。
从这天起，你的名字写在我家户口本上。
那天你穿婚纱的样子，够我看一辈子。
平安夜的雪，见证了我们的爱。

今夜陪你守岁，余生也陪你。
年味有你，就是最好的味道。
灯会人多，你的手抓紧别松开。
粽子飘香，我们去江边走走。
今天的星光，只为我们闪亮。
月亮再圆，也不及我们团圆。
秋高气爽，一起登高看风景。 --format lvgl -o my_font.c
 ******************************************************************************/

